# 2. WYBÓR ŹRÓDŁA — dla historycznych dni preferujemy run_id z Gold v1
# (żeby porównanie liczby ofert v1/v2 było porównywalne)
selected_snapshots = []

for day in silver_fs.listStatus(Path(silver_base)):
    if not day.isDirectory() or not day.getPath().getName().startswith("snapshot_date="):
        continue
    date_value = day.getPath().getName().removeprefix("snapshot_date=")
    completed = []
    for run in silver_fs.listStatus(day.getPath()):
        run_path = run.getPath()
        if run.isDirectory() and run_path.getName().startswith("run_id="):
            if silver_fs.exists(Path(str(run_path).rstrip("/") + "/_SUCCESS")):
                completed.append(run_path)
    if not completed:
        continue

    chosen = max(completed, key=lambda p: p.getName())
    v1_day = gold_v1_base + f"snapshot_date={date_value}/"
    if gold_fs.exists(Path(v1_day + "_SUCCESS")):
        v1_runs = [r[0] for r in spark.read.parquet(v1_day).select("run_id").distinct().collect()]
        if len(v1_runs) != 1:
            raise RuntimeError(f"{date_value}: Gold v1 nie ma dokładnie jednego run_id: {v1_runs}")
        expected_run_id = v1_runs[0]
        matches = [p for p in completed if p.getName() == f"run_id={expected_run_id}"]
        if not matches:
            raise RuntimeError(f"{date_value}: brak kompletnego Silver dla run_id z Gold v1: {expected_run_id}")
        chosen = matches[0]

    selected_snapshots.append((date_value, str(chosen)))

selected_snapshots.sort(key=lambda item: item[0])
if not selected_snapshots:
    raise RuntimeError("Brak ukończonych snapshotów Silver (_SUCCESS).")
for date_value, selected_path in selected_snapshots:
    print("WYBRANO:", date_value, selected_path)
